// banana2d test ROM: a 2D workout for the Nintendo DS, in eight phases of PHASE_FRAMES frames each,
// driven entirely by register writes from the ARM9 (no BIOS calls, no IRQs). It gives melonDS's two
// 2D renderers the same real-world input: graphics generated by a PRNG, scrolling text layers,
// sprites moving every frame, windows, blending, affine rotation, bitmaps, fades, mosaic, per-line
// raster effects from a VCOUNT poll, and a real 3D layer with translucent quads under 2D layers.
//
//   phase 0 text      3 text BGs (16/256-colour, extended palette) and 48 sprites on A; 2 BGs + 24 on B
//   phase 1 blend     + window 0 and 1, alpha BG1 over BG2, semi-transparent sprites, an OBJ window;
//                     B: a 256-colour bitmap BG and brightness-down
//   phase 2 storm     128 sprites on each engine, 16/256-colour, bitmap, rotscale, OBJ extended palette
//   phase 3 affine    two rotating affine BGs on A; mixed affine/text and direct-colour bitmap on B
//   phase 4 fade      bitmaps scrolling, BLDCNT brightness and master brightness ramping
//   phase 5 mosaic    BG and OBJ mosaic with a window
//   phase 6 raster    per-line scroll, window and BLDY changes, written during the scanline
//   phase 7 3d        BG0 as the 3D layer (translucent quads), HUD text BGs and semi-transparent sprites
//
// Copyright 2026 ROCKNIXDS contributors. MIT, like the rest of the ROCKNIXDS tools.
#include "tables.h"

typedef unsigned int u32; typedef unsigned short u16; typedef unsigned char u8; typedef int s32; typedef short s16;
#define R32(a) (*(volatile u32 *)(a))
#define R16(a) (*(volatile u16 *)(a))
#define R8(a)  (*(volatile u8 *)(a))

#define PHASE_FRAMES 60

// 2D engine registers: e = 0 (A) or 1 (B)
#define EB(e)        (0x04000000 + (e) * 0x1000)
#define DISPCNT(e)   R32(EB(e) + 0x00)
#define BGCNT(e,n)   R16(EB(e) + 0x08 + (n) * 2)
#define BGHOFS(e,n)  R16(EB(e) + 0x10 + (n) * 4)
#define BGVOFS(e,n)  R16(EB(e) + 0x12 + (n) * 4)
#define BGPA(e,n)    R16(EB(e) + 0x20 + ((n) - 2) * 0x10)
#define BGPB(e,n)    R16(EB(e) + 0x22 + ((n) - 2) * 0x10)
#define BGPC(e,n)    R16(EB(e) + 0x24 + ((n) - 2) * 0x10)
#define BGPD(e,n)    R16(EB(e) + 0x26 + ((n) - 2) * 0x10)
#define BGX(e,n)     R32(EB(e) + 0x28 + ((n) - 2) * 0x10)
#define BGY(e,n)     R32(EB(e) + 0x2C + ((n) - 2) * 0x10)
#define WIN0H(e)     R16(EB(e) + 0x40)
#define WIN1H(e)     R16(EB(e) + 0x42)
#define WIN0V(e)     R16(EB(e) + 0x44)
#define WIN1V(e)     R16(EB(e) + 0x46)
#define WININ(e)     R16(EB(e) + 0x48)
#define WINOUT(e)    R16(EB(e) + 0x4A)
#define MOSAIC(e)    R16(EB(e) + 0x4C)
#define BLDCNT(e)    R16(EB(e) + 0x50)
#define BLDALPHA(e)  R16(EB(e) + 0x52)
#define BLDY(e)      R16(EB(e) + 0x54)
#define MASTERBRIGHT(e) R16(EB(e) + 0x6C)

#define VCOUNT       R16(0x04000006)
#define POWCNT1      R32(0x04000304)
#define VRAMCNT_A    R8(0x04000240)
#define VRAMCNT_B    R8(0x04000241)
#define VRAMCNT_C    R8(0x04000242)
#define VRAMCNT_D    R8(0x04000243)
#define VRAMCNT_E    R8(0x04000244)
#define VRAMCNT_F    R8(0x04000245)
#define VRAMCNT_G    R8(0x04000246)
#define VRAMCNT_H    R8(0x04000248)
#define VRAMCNT_I    R8(0x04000249)

// 3D
#define DISP3DCNT    R32(0x04000060)
#define CLEAR_COLOR  R32(0x04000350)
#define CLEAR_DEPTH  R32(0x04000354)
#define GXSTAT       R32(0x04000600)
#define MTX_MODE     R32(0x04000440)
#define MTX_IDENT    R32(0x04000454)
#define MTX_LOAD44   R32(0x04000458)
#define POLY_ATTR    R32(0x040004A4)
#define TEX_PARAM    R32(0x040004A8)
#define GX_COLOR     R32(0x04000480)
#define GX_VTX16     R32(0x0400048C)
#define BEGIN_VTXS   R32(0x04000500)
#define END_VTXS     R32(0x04000504)
#define SWAP_BUF     R32(0x04000540)
#define VIEWPORT     R32(0x04000580)

#define PAL(e)       ((volatile u16 *)(0x05000000 + (e) * 0x400))
#define OBJPAL(e)    ((volatile u16 *)(0x05000200 + (e) * 0x400))
#define OAM(e)       ((volatile u16 *)(0x07000000 + (e) * 0x400))
#define ABG          ((volatile u8 *)0x06000000)
#define BBG          ((volatile u8 *)0x06200000)
#define AOBJ         ((volatile u8 *)0x06400000)
#define BOBJ         ((volatile u8 *)0x06600000)
#define LCDC_F       ((volatile u16 *)0x06890000)
#define LCDC_G       ((volatile u16 *)0x06894000)
#define LCDC_H       ((volatile u16 *)0x06898000)
#define LCDC_I       ((volatile u16 *)0x068A0000)

// the ARM EABI division helpers clang emits calls to (quotient in r0, remainder in r1)
static u32 udivmod(u32 n, u32 d, u32 *rem) {
    u32 q = 0, r = 0;
    for (int i = 31; i >= 0; i--) {
        r = (r << 1) | ((n >> i) & 1);
        if (r >= d) { r -= d; q |= 1u << i; }
    }
    *rem = r;
    return q;
}
unsigned long long __aeabi_uidivmod(u32 n, u32 d) { u32 r; u32 q = udivmod(n, d, &r); return q | ((unsigned long long)r << 32); }
u32 __aeabi_uidiv(u32 n, u32 d) { u32 r; return udivmod(n, d, &r); }
unsigned long long __aeabi_idivmod(s32 n, s32 d) {
    u32 r; u32 q = udivmod(n < 0 ? -n : n, d < 0 ? -d : d, &r);
    s32 sq = ((n < 0) != (d < 0)) ? -(s32)q : (s32)q;
    s32 sr = (n < 0) ? -(s32)r : (s32)r;
    return (u32)sq | ((unsigned long long)(u32)sr << 32);
}
s32 __aeabi_idiv(s32 n, s32 d) { return (s32)__aeabi_idivmod(n, d); }

void *memset(void *d, int c, unsigned long n) { unsigned char *p = d; while (n--) *p++ = (unsigned char)c; return d; }
void *memcpy(void *d, const void *s, unsigned long n) { unsigned char *p = d; const unsigned char *q = s; while (n--) *p++ = *q++; return d; }

static u32 rng = 0x12345678;
static u32 rnd(void) { rng ^= rng << 13; rng ^= rng >> 17; rng ^= rng << 5; return rng; }
static u32 rndn(u32 n) { return (u32)(((unsigned long long)rnd() * n) >> 32); }
static int chance(int pct) { return (int)rndn(100) < pct; }
static s32 sn(s32 a) { return sintab[a & 255]; }
static s32 cs(s32 a) { return sintab[(a + 64) & 255]; }

static void wait_vblank(void) {
    while (VCOUNT >= 192) {}
    while (VCOUNT < 192) {}
}

// ---- content ---------------------------------------------------------------------------------------

static void w32(volatile u8 *base, u32 off, u32 v) { *(volatile u32 *)(base + off) = v; }
static void w16(volatile u8 *base, u32 off, u16 v) { *(volatile u16 *)(base + off) = v; }

static void gen_tiles16(volatile u8 *base, u32 off, int n, int zeropct) {
    for (int t = 0; t < n; t++)
        for (int r = 0; r < 8; r++) {
            u32 v = 0;
            for (int k = 0; k < 8; k++) v |= (chance(zeropct) ? 0 : 1 + rndn(15)) << (k * 4);
            w32(base, off + t * 32 + r * 4, v);
        }
}

static void gen_tiles256(volatile u8 *base, u32 off, int n, int zeropct) {
    for (int t = 0; t < n; t++)
        for (int r = 0; r < 16; r++) {
            u32 v = 0;
            for (int k = 0; k < 4; k++) v |= (chance(zeropct) ? 0 : 1 + rndn(255)) << (k * 8);
            w32(base, off + t * 64 + r * 4, v);
        }
}

static void gen_textmap(volatile u8 *base, u32 off, int blocks, int ntiles, int palbits, int emptypct) {
    for (int i = 0; i < blocks * 1024; i++) {
        u16 e = rndn(ntiles);
        if (chance(emptypct)) e = 0;
        if (chance(30)) e |= 0x400;
        if (chance(30)) e |= 0x800;
        if (palbits) e |= rndn(16) << 12;
        w16(base, off + i * 2, e);
    }
}

static void gen_affinemap(volatile u8 *base, u32 off, int n, int ntiles) {
    for (int i = 0; i < n; i += 4) {
        u32 v = rndn(ntiles) | (rndn(ntiles) << 8) | (rndn(ntiles) << 16) | (rndn(ntiles) << 24);
        w32(base, off + i, v);
    }
}

static void gen_bitmap16(volatile u8 *base, u32 off, int w, int h, int alphapct) {
    for (int y = 0; y < h; y++)
        for (int x = 0; x < w; x += 2) {
            u16 a = (x & 31) | (((y >> 1) & 31) << 5) | ((((x + y) >> 2) & 31) << 10);
            u16 b = ((x + 1) & 31) | (((y >> 1) & 31) << 5) | ((((x + 1 + y) >> 2) & 31) << 10);
            if (chance(alphapct)) a |= 0x8000;
            if (chance(alphapct)) b |= 0x8000;
            w32(base, off + (y * w + x) * 2, a | (b << 16));
        }
}

static void gen_bitmap8(volatile u8 *base, u32 off, int n, int zeropct) {
    for (int i = 0; i < n; i += 4) {
        u32 v = 0;
        for (int k = 0; k < 4; k++) v |= (chance(zeropct) ? 0 : 1 + rndn(255)) << (k * 8);
        w32(base, off + i, v);
    }
}

static void gen_palette(volatile u16 *pal, int n) {
    for (int i = 0; i < n; i++) pal[i] = (u16)rnd();
}

static void gen_lcdc_pal(volatile u16 *lcdc, int words) {
    for (int i = 0; i < words; i++) lcdc[i] = (u16)rnd();
}

// ---- sprites ---------------------------------------------------------------------------------------

typedef struct { s16 x, y, dx, dy; u16 a0, a1, a2; } Sprite;
static Sprite spr[2][128];
static int nspr[2];

static void set_oam(int e, int i, u16 a0, u16 a1, u16 a2) {
    volatile u16 *o = OAM(e) + i * 4;
    o[0] = a0; o[1] = a1; o[2] = a2;
}

static void clear_oam(int e) {
    for (int i = 0; i < 128; i++) set_oam(e, i, 0x0200, 0, 0);
}

static void set_rot(int e, int g, s16 a, s16 b, s16 c, s16 d) {
    volatile u16 *o = OAM(e) + g * 16 + 3;
    o[0] = a; o[4] = b; o[8] = c; o[12] = d;
}

// a field of n sprites with random sizes, modes and tiles; they bounce around the screen
static void sprite_field(int e, int n, int semipct, int bitmappct, int rotpct, int winpct, int mosaicpct) {
    clear_oam(e);
    nspr[e] = n;
    for (int g = 0; g < 32; g++) {
        s32 ang = g * 11;
        s32 sc = 3072 + (g % 5) * 819;   // 0.75 .. 1.55
        s16 a = (s16)((cs(ang) * 256) / sc), b = (s16)((sn(ang) * 256) / sc);
        set_rot(e, g, a, -b, b, a);
    }
    for (int i = 0; i < n; i++) {
        Sprite *s = &spr[e][i];
        int shape = rndn(3), size = rndn(4);
        int mode = chance(semipct) ? 1 : 0;
        if (chance(winpct)) mode = 2;
        if (chance(bitmappct)) mode = 3;
        int c256 = chance(40);
        int rot = chance(rotpct);
        int dbl = rot && chance(30);
        int mosaic = chance(mosaicpct);
        int tile;
        if (mode == 3) tile = 0x180 + rndn(0x60);
        else if (c256) tile = 0x400 + (rndn(0x180) & ~1);
        else tile = rndn(0x3C0);
        s->x = (s16)(rndn(280) - 24); s->y = (s16)(rndn(210) - 16);
        s->dx = (s16)(rndn(5) - 2); s->dy = (s16)(rndn(5) - 2);
        s->a0 = (rot << 8) | (dbl << 9) | (mode << 10) | (mosaic << 12) | (c256 << 13) | (shape << 14);
        s->a1 = rot ? (rndn(32) << 9) | (size << 14) : (rndn(4) << 12) | (size << 14);
        s->a2 = tile | (rndn(4) << 10) | ((mode == 3 ? 1 + rndn(15) : rndn(16)) << 12);
    }
}

static void move_sprites(int e) {
    for (int i = 0; i < nspr[e]; i++) {
        Sprite *s = &spr[e][i];
        s->x += s->dx; s->y += s->dy;
        if (s->x < -40 || s->x > 260) s->dx = -s->dx;
        if (s->y < -40 || s->y > 200) s->dy = -s->dy;
        set_oam(e, i, (s->a0 & ~0xFF) | (s->y & 0xFF), (s->a1 & ~0x1FF) | (s->x & 0x1FF), s->a2);
    }
}

// ---- 3D -------------------------------------------------------------------------------------------

static void gx_wait(void) { while (GXSTAT & (1 << 27)) {} }

static void vtx(s32 x, s32 y, s32 z) {
    GX_VTX16 = ((u32)(u16)(s16)x) | ((u32)(u16)(s16)y << 16);
    GX_VTX16 = (u32)(u16)(s16)z;
}

static void draw_3d(int frame) {
    MTX_MODE = 0; MTX_IDENT = 0;      // projection: identity, so clip space is the screen
    MTX_MODE = 2; MTX_IDENT = 0;      // position+vector
    TEX_PARAM = 0;
    for (int q = 0; q < 6; q++) {
        s32 cx = sn(frame * 2 + q * 43) * 3 / 4;      // -3072 .. 3072 (4.12: 1.0 = 4096)
        s32 cy = cs(frame * 3 + q * 71) * 3 / 4;
        s32 r = 1200 + q * 150;
        u32 alpha = (q & 1) ? 8 + (q * 3 & 15) : 31;
        POLY_ATTR = (0xF << 16 & 0) | (alpha << 16) | (3 << 6) | (q << 24);   // no lights, both faces, alpha, id q
        BEGIN_VTXS = 1;   // quads
        GX_COLOR = (u32)rnd() & 0x7FFF;
        vtx(cx - r, cy - r, -(1000 + q * 300));
        vtx(cx + r, cy - r, -(1000 + q * 300));
        vtx(cx + r, cy + r, -(1000 + q * 300));
        vtx(cx - r, cy + r, -(1000 + q * 300));
        END_VTXS = 0;
    }
    gx_wait();
    SWAP_BUF = 0;
}

// ---- phases ----------------------------------------------------------------------------------------

static void common_regs(void) {
    for (int e = 0; e < 2; e++) {
        DISPCNT(e) = 0x00010000;
        for (int n = 0; n < 4; n++) { BGCNT(e, n) = 0; BGHOFS(e, n) = 0; BGVOFS(e, n) = 0; }
        for (int n = 2; n < 4; n++) { BGPA(e, n) = 0x100; BGPB(e, n) = 0; BGPC(e, n) = 0; BGPD(e, n) = 0x100; BGX(e, n) = 0; BGY(e, n) = 0; }
        WIN0H(e) = 0; WIN1H(e) = 0; WIN0V(e) = 0; WIN1V(e) = 0; WININ(e) = 0; WINOUT(e) = 0;
        MOSAIC(e) = 0; BLDCNT(e) = 0; BLDALPHA(e) = 0; BLDY(e) = 0; MASTERBRIGHT(e) = 0;
        clear_oam(e);
        nspr[e] = 0;
    }
}

// A: tiles 16c at 0x00000 (1024), 256c at 0x10000 (256); maps: BG0 0x8000, BG1 0x8800 (512x256), BG2 0x9800
// (256x512), BG3 0xA800; affine maps 0xB800 (32x32), 0xBC00 (64x64 = 4KB -> 0xBC00..0xCBFF);
// mixed map 16-bit 0xD000 (32x32); bitmaps in bank B at 0x20000 (direct 256x256) and 0x40000 (256c 256x256)
static void setup_text_a(int blend) {
    DISPCNT(0) = 0x40011F10;                                  // mode 0, BG0-3 + OBJ, 1D OBJ, BG ext pal
    BGCNT(0, 0) = 0x0000 | (0x10 << 8) | (0 << 2);                               // 16c, map 0x8000, prio 0
    BGCNT(0, 1) = 0x0001 | (0x11 << 8) | (4 << 2) | (1 << 7) | (1 << 14);        // 256c std, 512x256
    BGCNT(0, 2) = 0x0002 | (0x13 << 8) | (4 << 2) | (1 << 7) | (1 << 15);        // 256c ext pal slot 2, 256x512
    BGCNT(0, 3) = 0x0003 | (0x15 << 8) | (0 << 2);                               // 16c
    if (blend) {
        DISPCNT(0) |= 0xE000;                                 // win0, win1, OBJ window
        WININ(0) = 0x1B3F; WINOUT(0) = 0x372D;
        BLDCNT(0) = 0x0442 | 0x1000 | 0x0010;                 // BG1 + OBJ 1st, BG2 + OBJ 2nd, alpha
        BLDALPHA(0) = 9 | (7 << 8);
        sprite_field(0, 56, 30, 15, 0, 6, 0);
    } else
        sprite_field(0, 48, 0, 0, 0, 0, 0);
}

// B: tiles 16c at 0x0000 (512), 256c at 0x4000 (256); maps 0xC000 (BG0), 0xC800 (BG1), mixed 0xD000;
// bitmap 256c 256x256 at 0x10000, direct 128x128 at 0x8000 (32KB)
static void setup_text_b(void) {
    DISPCNT(1) = 0x00011310;
    BGCNT(1, 0) = 0x0000 | (0x18 << 8) | (0 << 2);
    BGCNT(1, 1) = 0x0001 | (0x19 << 8) | (1 << 2) | (1 << 7);
    sprite_field(1, 24, 0, 0, 0, 0, 0);
}

static void phase_setup(int phase) {
    common_regs();
    switch (phase) {
    case 0:
        setup_text_a(0);
        setup_text_b();
        break;
    case 1:
        setup_text_a(1);
        DISPCNT(1) = 0x00011505;                                  // mode 5: BG0 text, BG2 bitmap, OBJ
        BGCNT(1, 0) = 0x0000 | (0x18 << 8) | (0 << 2);
        BGCNT(1, 2) = 0x0001 | (0x04 << 8) | (1 << 7) | (1 << 14) | (1 << 13);   // 256c bitmap 256x256 at 0x10000, wrap
        BLDCNT(1) = 0x00C4 | 0x3F00;                              // brightness down on BG2
        BLDY(1) = 5;
        sprite_field(1, 32, 20, 20, 0, 0, 0);
        break;
    case 2:
        DISPCNT(0) = 0x80311310;                                  // OBJ ext pal, 1D, boundary 128
        BGCNT(0, 0) = 0x0001 | (0x10 << 8);
        BGCNT(0, 1) = 0x0002 | (0x11 << 8) | (4 << 2) | (1 << 7) | (1 << 14);
        sprite_field(0, 128, 20, 10, 15, 0, 0);
        DISPCNT(1) = 0x80311110;
        BGCNT(1, 0) = 0x0001 | (0x18 << 8);
        sprite_field(1, 128, 15, 10, 15, 3, 0);
        break;
    case 3:
        DISPCNT(0) = 0x00011C12;                                  // mode 2: BG2, BG3 affine, OBJ
        BGCNT(0, 2) = 0x0000 | (0x17 << 8) | (4 << 2) | (0 << 14) | (1 << 13);  // 256x256 wrap, map 0xB800
        BGCNT(0, 3) = 0x0001 | (0x18 << 8) | (4 << 2) | (3 << 14);              // 1024x1024?? no: size 3 = 1024; use 2 (512)
        BGCNT(0, 3) = 0x0001 | (0x18 << 8) | (4 << 2) | (2 << 14);              // 512x512 no wrap, map 0xC000
        sprite_field(0, 24, 0, 0, 40, 0, 0);
        DISPCNT(1) = 0x40011C15;                                  // mode 5: BG2 mixed, BG3 direct bitmap, OBJ, ext pal
        BGCNT(1, 2) = 0x0000 | (0x1A << 8) | (1 << 2) | (1 << 14) | (1 << 13);  // mixed 256x256 wrap, map 0xD000, tiles 0x4000
        BGCNT(1, 3) = 0x0001 | (0x02 << 8) | (1 << 7) | (1 << 2) | (0 << 14);   // direct 128x128 at 0x8000
        sprite_field(1, 16, 0, 0, 60, 0, 0);
        break;
    case 4:
        DISPCNT(0) = 0x00011D15;                                  // mode 5: BG0 text, BG2 direct, BG3 256c, OBJ
        BGCNT(0, 0) = 0x0000 | (0x15 << 8) | (0 << 2);
        BGCNT(0, 2) = 0x0001 | (0x08 << 8) | (1 << 7) | (1 << 2) | (1 << 14) | (1 << 13);   // direct 256x256 at 0x20000
        BGCNT(0, 3) = 0x0002 | (0x10 << 8) | (1 << 7) | (1 << 14) | (1 << 13);              // 256c 256x256 at 0x40000
        BLDCNT(0) = 0x00C4;                                       // brightness down, BG2 1st
        sprite_field(0, 20, 20, 30, 0, 0, 0);
        DISPCNT(1) = 0x00010406;                                  // mode 6: BG2 large
        BGCNT(1, 2) = 0x0000 | (2 << 14) | (1 << 13);             // 512x256 wrap
        break;
    case 5:
        DISPCNT(0) = 0x00013512;                                  // mode 2, BG0, BG2, OBJ, win0
        BGCNT(0, 0) = 0x0000 | (0x10 << 8) | (1 << 6);
        BGCNT(0, 2) = 0x0001 | (0x17 << 8) | (4 << 2) | (1 << 6) | (1 << 13);
        MOSAIC(0) = 3 | (2 << 4) | (4 << 8) | (5 << 12);
        WIN0H(0) = (40 << 8) | 220; WIN0V(0) = (20 << 8) | 170;
        WININ(0) = 0x3F; WINOUT(0) = 0x15;
        sprite_field(0, 40, 10, 10, 10, 0, 60);
        DISPCNT(1) = 0x00011110;
        BGCNT(1, 0) = 0x0000 | (0x18 << 8) | (1 << 6);
        MOSAIC(1) = 7 | (1 << 4) | (2 << 8);
        sprite_field(1, 40, 0, 0, 0, 0, 80);
        break;
    case 6:
        DISPCNT(0) = 0x00013712;                                  // mode 2, BG0, BG1, BG2, OBJ, win0
        BGCNT(0, 0) = 0x0000 | (0x10 << 8);
        BGCNT(0, 1) = 0x0001 | (0x11 << 8) | (4 << 2) | (1 << 7);
        BGCNT(0, 2) = 0x0002 | (0x17 << 8) | (4 << 2) | (1 << 13);
        WIN0H(0) = 255; WIN0V(0) = 192;
        WININ(0) = 0x3F; WINOUT(0) = 0x1C;
        BLDCNT(0) = 0x00C1 | 0x0003;
        sprite_field(0, 32, 20, 0, 0, 0, 0);
        DISPCNT(1) = 0x00011905;                                  // mode 5: BG0 text, BG3 direct bitmap, OBJ
        BGCNT(1, 0) = 0x0000 | (0x18 << 8);
        BGCNT(1, 3) = 0x0001 | (0x02 << 8) | (1 << 7) | (1 << 2) | (1 << 13);
        sprite_field(1, 16, 0, 0, 0, 0, 0);
        break;
    case 7:
        DISPCNT(0) = 0x00011718;                                  // mode 0: BG0 = 3D, BG1, BG2, OBJ
        BGCNT(0, 0) = 0x0001;
        BGCNT(0, 1) = 0x0000 | (0x10 << 8);
        BGCNT(0, 2) = 0x0002 | (0x11 << 8) | (4 << 2) | (1 << 7);
        BLDCNT(0) = 0x0441 | 0x2000;                              // 3D 1st, BG2 + backdrop 2nd, alpha
        BLDALPHA(0) = 8 | (8 << 8);
        sprite_field(0, 40, 40, 10, 0, 0, 0);
        DISPCNT(1) = 0x00011110;
        BGCNT(1, 0) = 0x0000 | (0x18 << 8);
        sprite_field(1, 30, 0, 0, 0, 0, 0);
        break;
    }
}

static void phase_frame(int phase, int f) {
    s32 t = f;
    switch (phase) {
    case 0: case 1:
        BGHOFS(0, 0) = t; BGVOFS(0, 0) = t / 2;
        BGHOFS(0, 1) = 100 - t * 2; BGVOFS(0, 1) = 20 + (sn(t * 3) >> 8);
        BGHOFS(0, 2) = 300 + t; BGVOFS(0, 2) = 40 + t * 3;
        BGHOFS(0, 3) = -t / 3;
        BGHOFS(1, 0) = t * 2; BGVOFS(1, 1) = t;
        if (phase == 1) {
            int w = 60 + (sn(t * 2) >> 6);
            WIN0H(0) = ((128 - w) << 8) | (128 + w);
            WIN0V(0) = ((96 - w / 2) << 8) | (96 + w / 2);
            WIN1H(0) = (180 << 8) | 60; WIN1V(0) = (100 << 8) | 30;
            BGX(1, 2) = (20 + t) << 8; BGY(1, 2) = (10 + t / 2) << 8;
        }
        break;
    case 2:
        BGHOFS(0, 1) = 50 + t; BGVOFS(0, 1) = 50 - t;
        break;
    case 3: {
        s32 a = t * 2;
        BGPA(0, 2) = (s16)((cs(a) * 7) >> 3); BGPB(0, 2) = (s16)((sn(a) * 7) >> 3);
        BGPC(0, 2) = (s16)(-(sn(a) * 7) >> 3); BGPD(0, 2) = (s16)((cs(a) * 7) >> 3);
        BGX(0, 2) = -(40 << 8) - (t << 7); BGY(0, 2) = (10 << 8) + (t << 6);
        s32 sc = 0x180 + (sn(t) >> 4);
        BGPA(0, 3) = (s16)sc; BGPB(0, 3) = (s16)(-(sn(a) >> 5)); BGPC(0, 3) = (s16)(sn(a) >> 5); BGPD(0, 3) = (s16)sc;
        BGX(0, 3) = (30 << 8) + (t << 8); BGY(0, 3) = -(20 << 8);
        BGPA(1, 2) = (s16)((cs(a) * 9) >> 3); BGPB(1, 2) = (s16)((sn(a) * 3) >> 3);
        BGPC(1, 2) = (s16)(-(sn(a) * 3) >> 3); BGPD(1, 2) = (s16)((cs(a) * 9) >> 3);
        BGX(1, 2) = (10 << 8) + (t << 6); BGY(1, 2) = (5 << 8);
        BGPA(1, 3) = (s16)((cs(-a) * 9) >> 4); BGPB(1, 3) = (s16)((sn(-a) * 9) >> 4);
        BGPC(1, 3) = (s16)(-(sn(-a) * 9) >> 4); BGPD(1, 3) = (s16)((cs(-a) * 9) >> 4);
        BGX(1, 3) = -(10 << 8); BGY(1, 3) = (t << 6);
        break; }
    case 4:
        BGHOFS(0, 0) = t; BGVOFS(0, 0) = 9;
        BGX(0, 2) = (37 + t) << 8; BGY(0, 2) = (100 - t) << 8;
        BGX(0, 3) = -(13 << 8) + (t << 7); BGY(0, 3) = (50 << 8) + (t << 7);
        BLDY(0) = (t / 4) & 0xF;
        MASTERBRIGHT(0) = 0x4000 | ((t / 3) & 0xF);
        BGX(1, 2) = (60 + t * 3) << 8; BGY(1, 2) = (12 + t) << 8;
        MASTERBRIGHT(1) = 0x8000 | ((t / 4) & 0xF);
        break;
    case 5:
        BGHOFS(0, 0) = 5 + t; BGVOFS(0, 0) = 3 + t / 2;
        BGPA(0, 2) = 0xC0 + (sn(t * 2) >> 6); BGPB(0, 2) = 0x20; BGPC(0, 2) = -0x30; BGPD(0, 2) = 0xD0;
        BGX(0, 2) = t << 7; BGY(0, 2) = t << 6;
        BGHOFS(1, 0) = t;
        MOSAIC(0) = ((t / 10) & 7) | (2 << 4) | (((t / 7) & 7) << 8) | (5 << 12);
        break;
    case 6:
        BGHOFS(0, 0) = t * 2;
        BGX(1, 3) = (sn(t * 3) * 30) >> 4;
        if (f == 20) MASTERBRIGHT(1) = 0x8000 | 8;
        if (f == 40) MASTERBRIGHT(1) = 0;
        break;
    case 7:
        BGHOFS(0, 1) = t; BGVOFS(0, 2) = 40 + t;
        BGHOFS(1, 0) = 8 + t;
        break;
    }
    move_sprites(0);
    move_sprites(1);
}

// phase 6: raster effects written during the scanline, as a game's HBlank handler would
static void raster_frame(int f) {
    int last = -1;
    while (1) {
        int v = VCOUNT;
        if (v >= 192) break;
        if (v != last) {
            last = v;
            BGHOFS(0, 0) = v + f * 2;
            BGHOFS(0, 1) = 40 + (sn((v + f * 4) * 3) >> 8);
            BLDY(0) = (v / 12) & 0xF;
            int w = 20 + ((sn(v * 2 + f * 4) + 4096) * 100 >> 13);
            WIN0H(0) = ((128 - w) << 8) | (128 + w);
            BGPA(0, 2) = (s16)(0x100 + (sn(v) * 0x60 >> 12));
            BGPC(0, 2) = (s16)(cs(v) * 0x20 >> 12);
            if ((v & 7) == 0) BGX(0, 2) += 0x80;
        }
    }
}

int main(void) {
    POWCNT1 = 0x820F;                 // both 2D engines, 3D geometry + render, A on top

    // load VRAM: palettes for extended palette banks first (through LCDC), then map everything
    VRAMCNT_F = 0x80; VRAMCNT_G = 0x80; VRAMCNT_H = 0x80; VRAMCNT_I = 0x80;
    gen_lcdc_pal(LCDC_F, 0x2000);      // A BG ext pal slots 0-1
    gen_lcdc_pal(LCDC_G, 0x1000);      // A OBJ ext pal
    gen_lcdc_pal(LCDC_H, 0x4000);      // B BG ext pal
    gen_lcdc_pal(LCDC_I, 0x1000);      // B OBJ ext pal
    VRAMCNT_A = 0x81;                  // ABG 0x00000
    VRAMCNT_B = 0x89;                  // ABG 0x20000
    VRAMCNT_C = 0x84;                  // BBG
    VRAMCNT_D = 0x84;                  // BOBJ
    VRAMCNT_E = 0x82;                  // AOBJ
    VRAMCNT_F = 0x84;                  // ABG ext pal slots 0-1
    VRAMCNT_G = 0x85;                  // AOBJ ext pal
    VRAMCNT_H = 0x82;                  // BBG ext pal
    VRAMCNT_I = 0x83;                  // BOBJ ext pal

    gen_palette(PAL(0), 256); gen_palette(OBJPAL(0), 256);
    gen_palette(PAL(1), 256); gen_palette(OBJPAL(1), 256);

    // A BG
    gen_tiles16(ABG, 0x00000, 1024, 30);
    gen_tiles256(ABG, 0x10000, 256, 25);
    gen_textmap(ABG, 0x08000, 1, 512, 1, 10);
    gen_textmap(ABG, 0x08800, 2, 256, 1, 30);
    gen_textmap(ABG, 0x09800, 2, 256, 1, 0);
    gen_textmap(ABG, 0x0A800, 1, 512, 1, 50);
    gen_affinemap(ABG, 0x0B800, 32 * 32, 256);
    gen_affinemap(ABG, 0x0C000, 64 * 64, 256);
    gen_textmap(ABG, 0x0D000, 1, 256, 1, 10);
    gen_bitmap16(ABG, 0x20000, 256, 256, 90);
    gen_bitmap8(ABG, 0x40000 - 0x20000 + 0x20000, 0, 0);   // (placeholder, no-op)
    // the 256-colour bitmap lives in the second half of bank B: ABG 0x30000..0x3FFFF is 64KB = 256x256
    gen_bitmap8(ABG, 0x30000, 256 * 256, 10);
    // B BG
    gen_tiles16(BBG, 0x00000, 512, 30);
    gen_tiles256(BBG, 0x04000, 256, 20);
    gen_bitmap16(BBG, 0x08000, 128, 128, 85);
    gen_bitmap8(BBG, 0x10000, 256 * 256, 5);
    gen_textmap(BBG, 0x0C000, 1, 512, 1, 5);
    gen_textmap(BBG, 0x0C800, 1, 256, 1, 40);
    gen_textmap(BBG, 0x0D000, 1, 256, 1, 10);
    // OBJ
    gen_tiles16(AOBJ, 0x0000, 1024, 35);
    gen_tiles256(AOBJ, 0x8000, 256, 35);
    gen_bitmap16(AOBJ, 0xC000, 128, 64, 70);
    gen_tiles16(BOBJ, 0x0000, 1024, 35);
    gen_tiles256(BOBJ, 0x8000, 256, 35);
    gen_bitmap16(BOBJ, 0xC000, 128, 64, 70);

    // 3D
    DISP3DCNT = 0x3 | (1 << 3);       // texture mapping, highlight shading, alpha blending
    CLEAR_COLOR = 0x00000000;         // transparent clear
    CLEAR_DEPTH = 0x7FFF;
    VIEWPORT = (0 | (0 << 8) | (255 << 16) | (191 << 24));
    gx_wait();
    SWAP_BUF = 0;

    int frame = 0;
    for (int phase = 0; phase < 8; phase++) {
        wait_vblank();
        phase_setup(phase);
        for (int f = 0; f < PHASE_FRAMES; f++, frame++) {
            wait_vblank();
            phase_frame(phase, f);
            if (phase == 7) draw_3d(f);
            if (phase == 6) { while (VCOUNT >= 192) {} raster_frame(f); }
            // a palette write every frame: a slow colour cycle on both engines
            PAL(0)[1 + (f & 63)] = (u16)rnd();
            OBJPAL(1)[1 + (f & 63)] = (u16)rnd();
        }
    }
    // done: both screens white, forever
    DISPCNT(0) = 0; DISPCNT(1) = 0;
    while (1) { wait_vblank(); }
    return 0;
}
